/**
 * Portrait photos of the demo audience, inlined as data URLs so the portal
 * carries them itself instead of fetching a separate asset.
 *
 * Keyed by audience member id. A member with no entry here falls back to
 * their avatarUrl, and then to the portal's initials circle.
 */

const JASPER =
  "data:image/jpeg;base64,\
";

const JOEP =
  "data:image/png;base64,\
";

export const AVATARS: Record<string, string> = {
  jasper: JASPER,
  joep: JOEP,
};
